<template><PageContainer><PageHeader eyebrow="CENTRE PLATEFORME" title="Centre Monitoring" description="Cockpit operationnel pour surveiller la disponibilite, les incidents, les alertes et la capacite d'EduSync."><template #actions><RouterLink v-if="dashboard" class="mon-btn mon-btn--primary" :to="dashboard.routePath"><Gauge/>Ouvrir le dashboard</RouterLink></template></PageHeader><SectionBlock title="Poste de supervision" description="Acces rapide aux vues autorisees par vos permissions effectives."><div class="mon-kpi-grid"><MonitoringKpiCard label="Acteur actif" :value="session.actorLabel" hint="Autorite de session" :icon="ShieldCheck"/><MonitoringKpiCard label="Perimetre" value="PLATEFORME" hint="Monitoring systeme" :icon="Globe2"/><MonitoringKpiCard label="Vues accessibles" :value="pages.length" hint="Selon permissions" :icon="LayoutDashboard"/></div></SectionBlock><SectionBlock title="Espaces Monitoring" description="Chaque espace reste specialise : lecture, investigation ou action autorisee."><div class="mon-home-grid"><RouterLink v-for="p in pages" :key="p.code" class="mon-home-card" :to="p.routePath"><div class="mon-home-card__top"><span>{{p.code}}</span><ArrowUpRight/></div><strong>{{p.label}}</strong><p>{{resume(p)}}</p></RouterLink></div></SectionBlock></PageContainer></template>
<script setup lang="ts">import {computed} from 'vue';import {RouterLink} from 'vue-router';import {ArrowUpRight,Gauge,Globe2,LayoutDashboard,ShieldCheck} from 'lucide-vue-next';import PageContainer from '../../../shared/layout/PageContainer.vue';import PageHeader from '../../../shared/layout/PageHeader.vue';import SectionBlock from '../../../shared/layout/SectionBlock.vue';import {sessionStore} from '../../../shared/auth/session.store';import {getAccessiblePages} from '../../../shared/doctrine/doctrine.resolver';import {activeContextStore} from '../../../shared/session/active-context.store';import type {FrontendPageDoctrine} from '../../../shared/doctrine/doctrine.types';import MonitoringKpiCard from '../components/MonitoringKpiCard.vue';import '../monitoring.css';const session=sessionStore.state;const pages=computed(()=>getAccessiblePages(session.actorCode,activeContextStore.state.governanceLevel).filter(p=>p.moduleCode==='MONITORING'&&p.routePath!=='/app/monitoring'&&!p.routePath.includes('/:')));const dashboard=computed(()=>pages.value.find(p=>p.routePath.endsWith('/dashboard')));const resume=(p:FrontendPageDoctrine)=>p.visibleActions.length?p.visibleActions.map(a=>a.label).join(' · '):p.sectionLabel;</script>
<style scoped>.mon-home-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:1rem}.mon-home-card{padding:1.15rem;border-radius:22px;background:linear-gradient(150deg,#fff,#f8fbfd);border:1px solid rgba(15,42,67,.09);text-decoration:none;color:#173149;box-shadow:0 12px 34px rgba(15,42,67,.055);transition:.2s}.mon-home-card:hover{transform:translateY(-3px);box-shadow:0 18px 42px rgba(15,42,67,.1)}.mon-home-card__top{display:flex;justify-content:space-between;color:#0c7895;font-size:.78rem;font-weight:800}.mon-home-card strong{display:block;margin:.7rem 0 .4rem;font-size:1.05rem}.mon-home-card p{margin:0;color:#68798b;font-size:.84rem;line-height:1.5}</style>
